// Shares side by side: the municipality picked against all Spain, one pair
// of bars per category, from a frame whose first column is the category and
// whose 'Selected' and 'All Spain' columns are percentages.
// @constants begin
const SERIES = [
  { field: 'Selected', color: '#FF9830' },
  { field: 'All Spain', color: '#8E8E8E' },
];
// @constants end

const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const frame = context.panel.data.series[0];
const fields = frame?.fields ?? [];
const categories = Array.from(fields[0]?.values ?? []);
const column = (name) => Array.from(fields.find((f) => f.name === name)?.values ?? []).map((v) => (v === null ? null : Number(v)));
const zone = context.grafana.replaceVariables('${zone:text}') || 'Selected';
const series = SERIES.map((s) => ({ ...s, name: s.field === 'Selected' ? zone : s.field, values: column(s.field) }));

return {
  backgroundColor: 'transparent',
  color: series.map((s) => s.color),
  legend: { top: 0, right: 0, textStyle: { color: muted }, itemWidth: 14 },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    valueFormatter: (v) => (v === null || v === undefined ? '–' : `${Number(v).toFixed(1)} %`),
  },
  grid: { left: 8, right: 24, top: 28, bottom: 4, containLabel: true },
  xAxis: {
    type: 'value',
    axisLabel: { color: muted, formatter: '{value} %' },
    splitLine: { lineStyle: { color: theme.colors.border.weak } },
  },
  yAxis: { type: 'category', data: categories, inverse: true, axisLabel: { color: muted } },
  series: series.map((s) => ({ name: s.name, type: 'bar', barGap: '10%', data: s.values })),
};

