// Trips by hour of the day picked, each line as a share of its own day, so a
// village and all Spain read on one scale: leaving the municipality picked,
// arriving in it, staying within it, and all Spain, dashed. The line across
// is the hour on the map's clock; a click on an hour moves the clock there.
// @constants begin
const FROM = 'map_from';
const TO = 'map_to';
const DAY = 'day';
const SERIES = [
  { scope: 'out', name: 'Leaving', color: '#FF9830' },
  { scope: 'in', name: 'Arriving', color: '#5794F2' },
  { scope: 'within', name: 'Within', color: '#73BF69' },
  { scope: 'spain', name: 'All Spain', color: '#8E8E8E', dashed: true },
];
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const read = (name) => context.grafana.replaceVariables('${' + name + '}');
const HOURS = Array.from({ length: 24 }, (_, h) => String(h).padStart(2, '0'));

const frame = context.panel.data.series[0];
const column = (name) => Array.from(frame?.fields.find((f) => f.name === name)?.values ?? []);
const scopes = column('scope');
const hours = column('hour').map(Number);
const trips = column('trips').map(Number);

const lines = SERIES.map((s) => {
  const raw = new Array(24).fill(0);
  scopes.forEach((scope, i) => {
    if (scope === s.scope) raw[hours[i]] += trips[i];
  });
  const total = raw.reduce((a, b) => a + b, 0);
  return { ...s, raw, total };
}).filter((s) => s.total > 0);

const clock = new Date(read(FROM));
const hour = Number.isNaN(clock.getTime()) ? null : clock.getUTCHours();
const day = read(DAY);

const pick = (h) => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) return;
  const hh = String(h).padStart(2, '0');
  location.partial({ ['var-' + FROM]: `${day}T${hh}:00:00.000Z`, ['var-' + TO]: `${day}T${hh}:59:59.999Z` }, true);
};
const zr = chart.getZr();
zr.off('click');
zr.on('click', (event) => {
  const at = [event.offsetX, event.offsetY];
  if (!chart.containPixel('grid', at)) return;
  const h = Math.round(chart.convertFromPixel({ xAxisIndex: 0 }, at));
  if (h >= 0 && h < 24) pick(h);
});

return {
  backgroundColor: 'transparent',
  color: lines.map((s) => s.color),
  legend: { top: 0, textStyle: { color: muted }, itemWidth: 14 },
  tooltip: {
    trigger: 'axis',
    formatter: (items) =>
      `${items[0].axisValue}:00–${items[0].axisValue}:59<br/>` +
      items
        .map((p) => {
          const s = lines[p.seriesIndex];
          return `${p.marker}${s.name}: <b>${Math.round(s.raw[p.dataIndex]).toLocaleString()}</b> trips, ${p.value.toFixed(1)} % of its day`;
        })
        .join('<br/>'),
  },
  grid: { left: 8, right: 16, top: 32, bottom: 8, containLabel: true },
  xAxis: {
    type: 'category',
    data: HOURS,
    boundaryGap: false,
    axisLabel: { color: muted },
    axisLine: { lineStyle: { color: theme.colors.border.medium } },
  },
  yAxis: {
    type: 'value',
    axisLabel: { color: muted, formatter: '{value} %' },
    splitLine: { lineStyle: { color: theme.colors.border.weak } },
  },
  series: lines.map((s, i) => ({
    name: s.name,
    type: 'line',
    smooth: true,
    showSymbol: false,
    lineStyle: { width: s.dashed ? 1.5 : 2, type: s.dashed ? 'dashed' : 'solid' },
    data: s.raw.map((v) => (100 * v) / s.total),
    markLine:
      i === 0 && hour !== null
        ? {
            silent: true,
            symbol: 'none',
            label: { show: false },
            lineStyle: { color: theme.colors.text.primary, type: 'solid', width: 1 },
            data: [{ xAxis: HOURS[hour] }],
          }
        : undefined,
  })),
};

