// Trips in Spain month by month, stacked by kind, from a frame (time, one
// column per kind). The month of the day picked is outlined.
// @constants begin
const KINDS = [
  { field: 'Within a province', color: '#73BF69' },
  { field: 'Between provinces', color: '#FF9830' },
  { field: 'To and from abroad', color: '#5794F2' },
];
const DAY = 'day';
// @constants end

const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const frame = context.panel.data.series[0];
const column = (name) => Array.from(frame?.fields.find((f) => f.name === name)?.values ?? []);
const months = column('time').map((t) => new Date(Number(t)).toISOString().slice(0, 7));
const picked = context.grafana.replaceVariables('${' + DAY + '}').slice(0, 7);
const at = months.indexOf(picked);
const short = (v) => (v >= 1e9 ? `${(v / 1e9).toFixed(1)} bn` : `${Math.round(v / 1e6)} M`);

return {
  backgroundColor: 'transparent',
  color: KINDS.map((k) => k.color),
  legend: { top: 0, textStyle: { color: muted }, itemWidth: 14 },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    valueFormatter: (v) => `${Math.round(Number(v)).toLocaleString()} trips`,
  },
  grid: { left: 8, right: 16, top: 28, bottom: 4, containLabel: true },
  xAxis: { type: 'category', data: months, axisLabel: { color: muted } },
  yAxis: {
    type: 'value',
    axisLabel: { color: muted, formatter: short },
    splitLine: { lineStyle: { color: theme.colors.border.weak } },
  },
  series: KINDS.map((k, i) => ({
    name: k.field,
    type: 'bar',
    stack: 'trips',
    barCategoryGap: '20%',
    data: column(k.field).map((v, j) =>
      j === at ? { value: Number(v), itemStyle: { borderColor: theme.colors.text.primary, borderWidth: 1.5 } } : Number(v)
    ),
  })),
};

